<?php
declare(strict_types=1);
require __DIR__.'/mon_reinforcement_fixture.php';
// Targeted source/date/maintenance recovery tests. All prices and HTTP responses are synthetic.
$cases=[];$dirs=[];$started=mon_monotonic();
function gp_assert(bool $ok,string $why='assertion'): void {if(!$ok)throw new RuntimeException($why);}
function gp_fault(callable $f,string $code): void {try{$f();}catch(MonFault $e){gp_assert($e->faultCode===$code,$e->faultCode);return;}throw new RuntimeException('missing '.$code);}
function gp_case(string $name,callable $f): void {global $cases;MonExecution::$active=null;MonExecution::$store=null;MonPreparation::reset();try{$f();$cases[]=['case'=>$name,'pass'=>true];}catch(Throwable $e){$cases[]=['case'=>$name,'pass'=>false,'error'=>$e->getMessage()];}}
function gp_dir(): string {global $dirs;$p=sys_get_temp_dir().'/mon-gap-'.bin2hex(random_bytes(8));mkdir($p,0700);$dirs[]=$p;return $p;}
function gp_daily(callable $transport,?MonStore $store=null): MonDaily {$store=$store??new MonStore(gp_dir());$config=progress_test_config($store->dir);$http=new MonHttp(null,$transport);return new MonDaily($http,new MonCollector($http,$store,$config),$config,$store);}
function gp_symbol(string $country='US'): stdClass {return(object)['symbol_id'=>$country==='US'?'US|NASDAQ|FIX':'JP|TSE|1234','country'=>$country,'exchange'=>$country==='US'?'NASDAQ':'TSE','symbol'=>$country==='US'?'FIX':'1234','name'=>'Synthetic issuer','currency'=>$country==='US'?'USD':'JPY','purpose'=>'synthetic','candidate_origin'=>['existing'],'is_held'=>false,'position'=>null,'tick_size'=>1,'tick_rule'=>$country==='US'?'US_NMS_0.01_CURRENT':'JPX_TOPIX500_CURRENT','source_codes'=>(object)['kis'=>null,'yahoo'=>$country==='US'?'FIX':'1234.T']];}
function gp_dates(): array {$days=[];$day=new DateTimeImmutable('2026-04-09');while($day->format('Y-m-d')<='2026-10-09'){if((int)$day->format('N')<=5)$days[]=$day->format('Y-m-d');$day=$day->modify('+1 day');}return $days;}
function gp_html(string $country='US'): string {$rows=[];foreach(array_reverse(gp_dates())as $i=>$date)$rows[]='{t:"'.$date.'",o:100,h:102,l:99,c:101,v:1000,a:77,ch:.5}';$ticker=$country==='US'?'FIX':'TYO-1234';$currency=$country==='US'?'USD':'JPY';return '<html>past prices are adjusted for stock splits '.($country==='US'?'ex:"NASDAQ"':'exchange_code:"TYO"').' curr:{main:"'.$currency.'",price:"'.$currency.'"} data:{id:1,symbol:"'.$ticker.'",source:"spg",updated:"synthetic",data:['.implode(',',$rows).']}</html>';}
function gp_fred(): string {$lines=[];foreach(gp_dates()as $date)$lines[]='#'.$date.'|100';return '<td>SP500</td>S&amp;P Dow Jones Indices<table id="data-table-observations"></table><div id="extra-rows">'.implode("\n",$lines).'</div>';}
function gp_nasdaq(): string {$rows=[];foreach(array_reverse(gp_dates())as $date)$rows[]=(object)['date'=>(new DateTimeImmutable($date))->format('m/d/Y'),'open'=>'$100','high'=>'$102','low'=>'$99','close'=>'$101','volume'=>'1,001'];return mon_json((object)['status'=>(object)['rCode'=>200],'data'=>(object)['symbol'=>'FIX','totalRecords'=>count($rows),'tradesTable'=>(object)['rows'=>$rows]]]);}
function gp_response(string $body,int $status=200,array $headers=[]): array {return ['status'=>$status,'headers'=>$headers,'body'=>$body];}
function gp_read(string $body): MonDaily {return gp_daily(static function()use($body){return gp_response($body);});}
function gp_stage_fixture(): array {
    $d=reinforcement_fixture();$symbol=gp_symbol();$sid=$symbol->symbol_id;$d->watchlist->symbols=[$symbol];$d->watchlist->detail_requests=new stdClass();$d->analysis->candidate_audit=[(object)['symbol_id'=>$sid,'eligibility'=>'unverified','evidence_ids'=>[],'origin'=>['existing'],'failed_checks'=>[],'rank'=>null]];
    $d->watchlist->calendar=(object)['valid_until'=>'2026-10-15T20:00:00Z','markets'=>[(object)['country'=>'US','timezone'=>'America/New_York','checked_at'=>'2026-10-08T20:00:00Z','sessions'=>[(object)['market_date'=>'2026-10-09','open_at'=>'2026-10-09T13:30:00Z','close_at'=>'2026-10-09T20:00:00Z']]]]];
    $d->analysis->market_summary=[(object)['country'=>'US','completed_bar_date'=>'2026-10-09','target_completed_bar_date'=>'2026-10-09','comparison_status'=>'verified']];
    $settings=['http_timeout_seconds'=>5,'request_spacing_seconds'=>0];$stock=gp_read(gp_html())->stockAnalysis($symbol,'2026-10-09',microtime(true)+10,$settings);$stock->origin->checked_at='2026-10-11T11:00:00Z';$index=gp_read(gp_fred())->fred($symbol,'2026-10-09',microtime(true)+10,$settings);$index->origin->checked_at='2026-10-11T11:00:00Z';
    $s=MonDetails::snapshot($symbol,$stock->bars,$index->bars,'US|INDEX|^GSPC',$stock->origin,$index->origin);return [$d,$s,'2026-10-11T20:00:00Z'];
}

gp_case('FRED official table provides the same S&P price index and latest date',function(){$r=gp_read(gp_fred())->fred(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);gp_assert(count($r->bars)>100&&end($r->bars)[0]==='2026-10-09'&&$r->origin->benchmark_id==='US|INDEX|^GSPC');});
gp_case('HTTP200 browser challenge is never a valid index response',function(){gp_fault(static function(){gp_read('<html>verify your browser</html>')->fred(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_FRED_RESPONSE_INVALID');});
gp_case('FRED wrong series is rejected',function(){gp_fault(static function(){gp_read(str_replace('SP500','NASDAQCOM',gp_fred()))->fred(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_FRED_RESPONSE_INVALID');});
gp_case('FRED malformed values are rejected',function(){gp_fault(static function(){gp_read(str_replace('2026-10-09|100','2026-10-09|NaN',gp_fred()))->fred(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_FRED_VALUE_INVALID');});
gp_case('FRED missing final completed bar remains missing',function(){gp_fault(static function(){gp_read(str_replace('#2026-10-09|100','',gp_fred()))->fred(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_BENCHMARK_DATE_MISSING');});
gp_case('FRED duplicate session cannot fill a missing bar',function(){gp_fault(static function(){gp_read(str_replace('</div>','#2026-10-09|100</div>',gp_fred()))->fred(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_FRED_DUPLICATE_DATE');});
gp_case('S&P fallback cannot stand in for TOPIX',function(){gp_fault(static function(){gp_read(gp_fred())->fred(gp_symbol('JP'),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_FRED_ID_INVALID');});
gp_case('US alternative reads split-adjusted close rather than total-return adjusted close',function(){$r=gp_read(gp_html())->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);gp_assert($r->bars[0][4]===101.0&&$r->origin->complete_source_window&&$r->origin->price_basis===MonDetails::BASIS);});
gp_case('Japanese alternative verifies currency and exchange independently',function(){$r=gp_read(gp_html('JP'))->stockAnalysis(gp_symbol('JP'),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);gp_assert(count($r->bars)>100&&end($r->bars)[0]==='2026-10-09');});
foreach(['ticker'=>['symbol:"FIX",source','symbol:"OTHER",source'],'currency'=>['main:"USD",price:"USD"','main:"JPY",price:"JPY"'],'venue'=>['ex:"NASDAQ"','ex:"NYSE"'],'basis'=>['past prices are adjusted for stock splits','unknown basis']]as $name=>$change)gp_case('alternative rejects incorrect '.$name,function()use($change){gp_fault(static function()use($change){gp_read(str_replace($change[0],$change[1],gp_html()))->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_ALTERNATIVE_RESPONSE_INVALID');});
gp_case('alternative literal parser never evaluates JavaScript',function(){gp_fault(static function(){gp_read(str_replace('c:101','c:process.exit()',gp_html()))->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_ALTERNATIVE_ROW_INVALID');});
gp_case('alternative rejects duplicate dates',function(){gp_fault(static function(){gp_read(str_replace('2026-10-08','2026-10-09',gp_html()))->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);},'DETAIL_ALTERNATIVE_DUPLICATE_DATE');});
gp_case('Nasdaq raw history is not silently labelled split adjusted',function(){$r=gp_read(gp_nasdaq())->nasdaqRaw(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);gp_assert($r->origin->price_basis==='provider_basis_unverified');});
