gp_case('complete-window correction corroborates every close and preserves volume differences',function(){$settings=['http_timeout_seconds'=>5,'request_spacing_seconds'=>0];$s=gp_read(gp_html())->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,$settings);$n=gp_read(gp_nasdaq())->nasdaqRaw(gp_symbol(),'2026-10-09',microtime(true)+10,$settings);$proof=MonDaily::wholeWindowProof($s,$n);gp_assert($proof->verified_close_count===count($s->bars)&&$proof->volume_difference_count===count($s->bars));});
gp_case('one discrepant close blocks a complete-window correction',function(){$settings=['http_timeout_seconds'=>5,'request_spacing_seconds'=>0];$s=gp_read(gp_html())->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,$settings);$n=gp_read(gp_nasdaq())->nasdaqRaw(gp_symbol(),'2026-10-09',microtime(true)+10,$settings);$n->bars[20][4]=100.9;gp_fault(static function()use($s,$n){MonDaily::wholeWindowProof($s,$n);},'DETAIL_SOURCE_REPLACEMENT_UNVERIFIED');});
gp_case('incomplete history cannot approve source replacement',function(){$settings=['http_timeout_seconds'=>5,'request_spacing_seconds'=>0];$s=gp_read(gp_html())->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,$settings);$n=gp_read(gp_nasdaq())->nasdaqRaw(gp_symbol(),'2026-10-09',microtime(true)+10,$settings);$s->origin->complete_source_window=false;gp_fault(static function()use($s,$n){MonDaily::wholeWindowProof($s,$n);},'DETAIL_SOURCE_REPLACEMENT_UNVERIFIED');});
gp_case('all new providers honor the socket timeout and 429 circuit',function(){$calls=[];$http=new MonHttp(null,static function($m,$url,$h,$b,$timeout)use(&$calls){$calls[]=$timeout;return gp_response('{}',429,['retry-after'=>'90']);});foreach(['stockanalysis.com','api.nasdaq.com','fred.stlouisfed.org']as $host){$http->request('GET','https://'.$host.'/a',[],null,microtime(true)+10,5);gp_fault(static function()use($http,$host){$http->request('GET','https://'.$host.'/b',[],null,microtime(true)+10,5);},'HTTP_CIRCUIT_OPEN');}gp_assert(count($calls)===3&&max($calls)<=5);});
gp_case('before-close discovery uses today rather than previous completed-bar day',function(){$d=reinforcement_fixture();$sid=$d->watchlist->symbols[0]->symbol_id;$r=$d->watchlist->detail_requests->$sid;$r->symbol->candidate_group='new';$r->symbol->first_seen_at=mon_iso();$r->symbol->identity_evidence_ids=['identity'];$r->request_hash=MonDetails::requestHash($r);$p=MonRun::payload($d);$p->evidence_archive->identity=(object)['id'=>'identity','symbol_id'=>$sid,'source_kind'=>'independent','source_url'=>'https://example.invalid/identity','checked_at'=>mon_iso(),'claim'=>'synthetic identity','identity'=>(object)['name'=>$r->symbol->name,'country'=>'KR','symbol'=>$r->symbol->symbol,'venue'=>'KOSPI','currency'=>'KRW']];$d->analysis->evidence=[$p->evidence_archive->identity];$state=MonDiscovery::counts($d,$p,['full_signals'=>new stdClass()],mon_iso());gp_assert($state->countries[0]->new_ids_identified_today===1&&$state->countries[0]->discovery_date!==$state->countries[0]->completed_bar_date);});
gp_case('off-day discoveries cannot backfill a prior trading-day shortage',function(){$d=reinforcement_fixture();$d->watchlist->calendar->markets[0]->sessions=[];$d->analysis->discovery_state=(object)['countries'=>[(object)['country'=>'KR','market_date'=>'2026-10-09','completed_bar_date'=>'2026-10-09','daily_target'=>20,'new_ids_identified_today'=>0,'daily_goal_met'=>false]]];$s=MonDiscovery::counts($d,MonRun::payload($d),['full_signals'=>new stdClass()],mon_iso());gp_assert($s->countries[0]->goal_status==='not_due'&&!$s->countries[0]->daily_goal_met&&$s->previous_days[0]->shortfall===20);});
gp_case('coverage cannot claim goal met when evidence-backed count is zero',function(){$d=reinforcement_fixture();$d->analysis->coverage[0]->daily_goal_already_met=true;$d->analysis->discovery_state=(object)['countries'=>[(object)['country'=>'KR','market_date'=>'2026-10-09','completed_bar_date'=>'2026-10-09','daily_target'=>20,'new_ids_identified_today'=>0,'daily_goal_met'=>false]]];MonDiscovery::coverage($d);gp_assert(!$d->analysis->coverage[0]->daily_goal_already_met&&$d->analysis->coverage[0]->discovery_shortfall===20);});
gp_case('missing discovery evidence clears stale success flags',function(){$d=reinforcement_fixture();$d->analysis->coverage[0]->daily_goal_already_met=true;MonDiscovery::coverage($d);gp_assert(!$d->analysis->coverage[0]->daily_goal_already_met);});
gp_case('gap plan is read only and paginated; it never claims new selection',function(){$d=reinforcement_fixture();$before=MonRun::json($d);$p=MonGaps::plan($d,mon_iso());gp_assert(MonRun::json($d)===$before&&!$p['pages'][0]['header']['new_analysis_complete']);foreach($p['pages']as $page)gp_assert(strlen(MonRun::json((object)$page))<=12288);});
gp_case('gap report distinguishes waiting regular session from live-price success',function(){$d=reinforcement_fixture();$d=mon_decode(MonDetails::finalize($d,reinforcement_decision($d,reinforcement_context($d)))['files'][0]['content']);$d->watchlist->calendar->markets[0]->sessions=[];$r=MonGaps::plan($d,mon_iso());$seen=false;foreach($r['pages']as $page)foreach($page['cards']as $card)if($card->kind==='current_entry_checks'){$seen=true;gp_assert($card->state==='waiting_regular_session'&&!$card->resolved&&!$card->closed_price_substitutes_live);}gp_assert($seen);});
gp_case('cash dividend metadata does not substitute total-return adjusted close',function(){$r=gp_read(str_replace('ch:.5','ch:.5,div:.63',gp_html()))->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,['http_timeout_seconds'=>5,'request_spacing_seconds'=>0]);gp_assert($r->bars[0][4]===101.0);});
gp_case('large raw-record transport deduplicates and restores losslessly',function(){[$d,$s,$at]=gp_stage_fixture();$encoded=MonDetails::pack($s);$round=MonDetails::unpack($encoded);gp_assert(MonRun::json($s)===MonRun::json($round)&&strlen($encoded->data)<=MonDetails::MAX_PACKED);});
