gp_case('source maintenance preserves old decisions, analysis time and collection',function(){[$d,$s,$at]=gp_stage_fixture();$r=MonGaps::stage($d,[(object)['snapshot'=>$s]],$at);gp_assert($r['validation']['collection_preserved']&&$r['validation']['analysis_as_of_preserved']&&$r['validation']['result_fingerprint_preserved']&&$r['validation']['staged_count']===1&&count($r['files'])===3);});
