gp_case('future source timestamps remain quarantined',function(){[$d,$s,$at]=gp_stage_fixture();$s->origin->checked_at='2026-10-12T20:00:00Z';$s=MonDetails::snapshot($s->symbol,$s->bars,$s->benchmark_bars,$s->benchmark_id,$s->origin,$s->benchmark_origin);$r=MonGaps::stage($d,[(object)['snapshot'=>$s]],$at);gp_assert($r['validation']['staged_count']===0&&count($r['validation']['rejected'])===1);});
gp_case('staged sources clear pending state only in the working preparation copy',function(){[$d,$s,$at]=gp_stage_fixture();$r=MonGaps::stage($d,[(object)['snapshot'=>$s]],$at);$pending=MonRun::json($r['data']);$input=MonDetails::inputs($r['data'],(object)['source_blob_sha'=>MonRun::gitSha($pending),'rendered_at'=>$at,'countries'=>['US'],'important_ids'=>[]]);gp_assert($r['data']->analysis->pending_analysis&&!$input->analysis->pending_analysis&&MonRun::json($r['data'])===$pending&&MonRun::payload($input)->candidate_metrics->{$s->symbol_id}->bars_as_of==='2026-10-09');});
