gp_case('raw source references restore the exact immutable record',function(){[$d,$s,$at]=gp_stage_fixture();$r=MonGaps::stage($d,[(object)['snapshot'=>$s]],$at);$input=MonDetails::inputs($r['data'],(object)['source_blob_sha'=>MonRun::gitSha(MonRun::json($r['data'])),'rendered_at'=>$at,'countries'=>['US'],'important_ids'=>[]]);$h=MonRun::payload($input)->history_metadata->{$s->symbol_id};$records=MonGaps::rawRecords($h->raw_records_source_ref);gp_assert(MonRun::json($records)===MonRun::json($s->origin->raw_records));});
gp_case('prior history accepts a near closing price while preserving raw records',function(){$settings=['http_timeout_seconds'=>5,'request_spacing_seconds'=>0];$stock=gp_read(gp_html())->stockAnalysis(gp_symbol(),'2026-10-09',microtime(true)+10,$settings);$prior=(object)['bars'=>$stock->bars,'origin'=>(object)['source_url'=>'https://query1.finance.yahoo.com/v8/finance/chart/FIX'],'history_metadata'=>(object)['price_basis'=>MonDetails::BASIS,'checked_at'=>mon_iso()]];$prior->bars[20][4]=101.0001;$proof=MonDaily::priorWindowProof($prior,$stock);gp_assert($proof->approximate_close_count===1&&$prior->bars[20][4]===101.0001&&$stock->bars[20][4]===101.0);});
gp_case('identical old source inputs keep existing finalization behavior',function(){$d=reinforcement_fixture();$decision=reinforcement_decision($d,reinforcement_context($d));$r=MonDetails::finalize($d,$decision);$saved=mon_decode($r['files'][0]['content']);gp_assert(MonRun::json($d->collection)===MonRun::json($saved->collection)&&$saved->analysis->results[0]->action==='BUY_REVIEW');});
function gp_jpx(string $classification='TOPIX Small 1'): stdClass {$s=gp_symbol('JP');$s->tick_rule=$classification==='TOPIX Small 1'?'JPX_OTHER_CURRENT':'JPX_TOPIX500_CURRENT';$s->tick_rule_evidence=(object)['classification'=>$classification,'valid_from'=>'2026-08-31','valid_until'=>'2026-10-29','rules_url'=>'https://www.jpx.co.jp/english/equities/trading/domestic/07.html','membership_url'=>'https://www.jpx.co.jp/automation/markets/indices/topix/files/topixweight_j.csv','membership_sha256'=>str_repeat('a',64),'rules_sha256'=>str_repeat('b',64)];return $s;}
gp_case('JPX other-issue price bands round an upper boundary correctly',function(){$m=new ReflectionMethod(MonDetails::class,'roundTick');$m->setAccessible(true);$s=gp_jpx();gp_assert($m->invoke(null,$s,3000.1,true)===3005.0&&$m->invoke(null,$s,5000.1,true)===5010.0&&$m->invoke(null,$s,5000.1,false)===5000.0);});
