gp_case('streamed meaning hash matches canonical stable JSON including associative arrays',function(){
    $stable=static function($v)use(&$stable){if($v instanceof stdClass){$o=new stdClass();foreach($v as $k=>$x)if(!in_array($k,MonMeaning::VOLATILE,true))$o->$k=$stable($x);return $o;}if(is_array($v))return array_map($stable,$v);return $v;};
    $value=(object)['z'=>[(object)['as_of'=>'ignored','quoted'=>'한글 "/','n'=>1.0],['b'=>2,'a'=>1],[],(object)[]],'a'=>-0.0,'as_of'=>'ignored'];
    $m=new ReflectionMethod(MonMeaning::class,'digest');$m->setAccessible(true);gp_assert($m->invoke(null,$value)===hash('sha256',MonRun::json($stable($value))));
});
gp_case('streamed meaning preserves exact numeric and array-order changes',function(){
    $m=new ReflectionMethod(MonMeaning::class,'digest');$m->setAccessible(true);gp_assert($m->invoke(null,[1,2])!==$m->invoke(null,[2,1])&&$m->invoke(null,[1])!==$m->invoke(null,[1.0])&&$m->invoke(null,[100.0001])!==$m->invoke(null,[100.0002]));
});
gp_case('large old archives are preserved losslessly outside the working file',function(){
    [$d,$s,$at]=gp_stage_fixture();$p=MonRun::payload($d);$p->strategy_archive=(object)['old'=>(object)['analysis_note'=>str_repeat('synthetic archived fact ',6000),'past_as_of'=>'2026-10-01T20:00:00Z']];$original=MonRun::json($p->strategy_archive);
    $d->analysis->input_snapshot->lossless_payload=MonRun::pack($p,'gzip+base64');$r=MonGaps::stage($d,[(object)['snapshot'=>$s]],$at);gp_assert(count($r['files'])===4&&$r['validation']['archive_preserved_externally']&&MonRun::json(MonGaps::archived($r['data']))===$original);
